package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;

/**
 * The late charge on a sheet as of its today: an overdue claim (OPEN or PENDING, its due-by — its date plus the terms — before
 * today) gains the late percent of its figure for every full 30 days it is overdue, rounded to two
 * decimals by the claim's rounding (see Rounding). The charge is never bound by a statement (it follows today); settling freezes it into the claim's due.
 */
public record LateCharge(LocalDate today, int terms, BigDecimal pct, Rounding rounding) {

    /** The days in each step of the charge. */
    public static final int DAYS = 30;

    public static LateCharge of(String sheetId, SheetRepository sheets, SettingRepository settings,
            ClaimRepository claims) {
        return new LateCharge(sheets.today(sheetId), settings.terms(sheetId), settings.latePct(sheetId),
                Rounding.of(sheetId, sheets, settings, claims));
    }

    /** The charge on the claim with the given figure: zero when it is not overdue a full 30 days, has no figure, or
     *  is a correction. */
    public BigDecimal on(Claim claim, BigDecimal figure) {
        if (figure == null || !ClaimDue.isOpen(claim) || claim.due() != null || ClaimDue.isCorrection(claim)) {
            return BigDecimal.ZERO.setScale(2);
        }
        long overdue = ChronoUnit.DAYS.between(claim.date().plusDays(terms), today);
        long steps = overdue <= 0 ? 0 : overdue / DAYS;
        return figure.multiply(pct).multiply(BigDecimal.valueOf(steps)).movePointLeft(2)
                .setScale(2, rounding.mode(claim));
    }

    /** The figure with its charge added on top; null when it has none. */
    public BigDecimal add(Claim claim, BigDecimal figure) {
        return figure == null ? null : figure.add(on(claim, figure));
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Adds the claim to the person; a claim given no date is dated the sheet's today. A claim dated inside a closed
 *  period, or after the person's retirement date, is refused, as is a
 *  negative amount that does not correct a SETTLED claim of the person (see Corrections). */
public class AddClaim {
    public void add(@Val Person person, @Val ClaimValues values, SheetRepository sheets, ClaimRepository claims,
            PeriodRepository periods, Out<Claim> claim) throws InvalidClaimException {
        LocalDate date = values.date() != null ? values.date() : sheets.today(person.sheetId());
        if (periods.closedOn(person.sheetId(), date)) {
            throw new InvalidClaimException("The claim's date is inside a closed period");
        }
        if (!person.mayClaimOn(date)) {
            throw new InvalidClaimException("The claim's date is after the person's retirement date");
        }
        claim.set(claims.add(person.sheetId(), person.id(), values.amount(), date, values.note(),
                Corrections.check(person.sheetId(), person.id(), values, claims)));
    }
}
package net.officefloor.hq.app.claim;

/** A claim as sent to the screen: the amount as text with two decimals, so it is never rounded through a float;
 *  the number is null when the claim has none; due is the due fixed when settled (two decimals), null while it is
 *  live; openedBy is who opened it, null when never opened; stated is whether it is bound to the figure statedDue
 *  (two decimals, null when it had none) by its person's last statement; corrects is the number of the claim a
 *  correction corrects (null for any other claim); roundsOn is the date that decides how its live figures round
 *  (the corrected claim's date for a correction, else its own; see Rounding). */
public record ClaimResponse(long id, String sheetId, long personId, String amount, String date, String note,
        String status, String number, String due, String openedBy, boolean stated, String statedDue, String corrects,
        String roundsOn) {
    public static ClaimResponse from(Claim claim, ClaimRepository claims) {
        return new ClaimResponse(claim.id(), claim.sheetId(), claim.personId(), claim.amount().toPlainString(),
                claim.date().toString(), claim.note(), claim.status().name(), claim.number(),
                claim.due() == null ? null : claim.due().toPlainString(), claim.openedBy(), claim.stated(),
                claim.statedDue() == null ? null : claim.statedDue().toPlainString(), claim.corrects(),
                Rounding.roundsOn(claim, claims).toString());
    }
}

